"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[995],{3376:(e,t,a)=>{a.d(t,{FW:()=>i,HQ:()=>d,I9:()=>h,LR:()=>r,ME:()=>s,Yt:()=>c,dt:()=>n});let s={name:"Roshni Thakor",role:"Full Stack Developer",location:"Ahmedabad, India",email:"roshni.thakor.dev@gmail.com",github:"https://github.com/roshnithakor07",linkedin:"https://linkedin.com/in/roshnithakor07",hackerrank:"https://www.hackerrank.com/profile/roshnithakor07",resume:"/Roshni_Thakor_Software_Developer.pdf",altSite:{href:"https://roshnithakor07.github.io/v2/",label:"Notebook version (v2)",short:"Portfolio v2",note:"same work, a hand-made notebook design",lead:"Prefer paper?",cta:"Flip through the notebook version",cmd:"v2"},photo:"",summary:"Full stack developer with 3.9 years shipping production systems: multi-tenant APIs, security analytics over hundreds of millions of records, and AI features teams use every day."},o={eventus:{src:"/logos/eventus.png",alt:"Eventus Security",dark:!0,wide:!0},smile:{src:"/logos/smile-shree-maruti.png",alt:"Smile HRMS, powered by Shree Maruti",wide:!0},kanhasoft:{src:"/logos/kanhasoft.png",alt:"Kanhasoft"},flusocial:{src:"/logos/flusocial.png",alt:"Flu Social Marketing",wide:!0},letsgrowmore:{src:"/logos/letsgrowmore.png",alt:"LetsGrowMore",wide:!0}},r=[{company:"Shree Maruti",url:"https://shreemaruti.com/",logos:[o.smile,o.kanhasoft],via:"via Kanhasoft",title:"Backend Engineer",when:"Sep 2026 - Nov 2026",product:"Smile HRMS",summary:"Building the backend of a multi-tenant HR platform: leave, expenses, access control and offer letters.",stack:["NestJS","Fastify","PostgreSQL","TypeORM","AWS S3"],points:["Shipped the Leave Management module end to end: policies, balances and approval workflows with multi-organization data isolation.","Built Expenses with S3 signed-URL receipts, currency-locked exchange rates and versioned policy documents.","Implemented JWT auth and permission-code RBAC with org-scoped access, backed by 242+ unit tests."]},{company:"Eventus Security",url:"https://eventussecurity.com/",logos:[o.eventus],via:"",title:"Software Developer",when:"Sep 2022 - Jun 2026",product:"ESDL SOC Dashboard \xb7 DevLens \xb7 Health Check Automation",summary:"Built security analytics for India’s power grid, an AI code reviewer the team used daily, and a report engine that turned 20 hours into 1.",stack:["Next.js","NestJS","ClickHouse","MongoDB","Redis","Claude API"],points:["Led full-stack development of the SOC/EDR analytics dashboard monitoring critical infrastructure on India’s regional power grid.","Moved heavy analytics from MongoDB to ClickHouse and cached date-range queries in Redis, speeding up dashboards without scaling hardware.","Architected DevLens, an AI code-review platform; a streaming pipeline cut perceived latency from 8 s to under 1 s.","Automated customer health-check reports from 16–20 hours to under 1 hour, hardened with 2FA and VAPT fixes."]},{company:"Flu Social \xb7 LetsGrowMore",logos:[o.flusocial,o.letsgrowmore],companies:[{name:"Flu Social",url:"https://flusocial.com/"},{name:"LetsGrowMore",url:"https://letsgrowmore.in/"}],via:"",title:"Web Development Intern",when:"Sep 2021 - May 2022",product:"Internships",summary:"Two internships alongside my degree, building client sites and full-stack features.",stack:["WordPress","PHP","Angular","Express","MongoDB"],points:["Flu Social (Jan - May 2022): WordPress and PHP sites with MySQL, plus on-page SEO.","LetsGrowMore (Sep - Oct 2021): Angular 11 front ends on an Express and MongoDB backend."]}],n=[{name:"DevLens",trace:"devlens",kind:"AI code review platform",blurb:"Reviews only the changed Git hunks with the Claude API and streams findings back in under a second. Adopted daily by the engineering team for PR and security review.",stack:["NestJS","Next.js","MongoDB","Claude API"],stat:"8 s → <1 s",featured:!0,ai:!0,shot:{src:"/work/devlens.svg",alt:"Illustration of a DevLens code review: a diff with streamed AI review comments"},story:{context:"Internal AI code-review platform at Eventus Security",problem:"Developers reviewed every pull request by hand, so reviews took time and their quality depended on who picked them up.",built:["Backend APIs in NestJS and the AI integration, so DevLens reads a pull request and suggests code improvements and security issues.","A diff-parsing engine that scopes the analysis to the changed Git hunks only.","JWT authentication and role-based access with NestJS Guards: developers, reviewers and admins each get different permissions."],challenge:{title:"Making an 8-second AI review feel instant",body:"The first version waited for the complete AI result, around 8 seconds, which felt slow. I switched to streaming responses: suggestions appear as they are generated, like ChatGPT, so developers see the first feedback almost immediately."},result:"After deployment the team used DevLens daily for pull-request reviews. It cut manual effort, sped up reviews and made feedback more consistent.",before:{label:"Perceived AI latency",from:"~8 s",to:"< 1 s"}}},{name:"ESDL Dashboard",trace:"esdl",kind:"SOC analytics",blurb:"Real-time KPIs and threat views over hundreds of millions of records for power-grid security.",stack:["Next.js","ClickHouse","ECharts","Redis"],stat:"100M+ rows",spotlight:{where:"At work \xb7 Eventus Security",outcome:"Real-time KPIs over hundreds of millions of records \xb7 MongoDB → ClickHouse \xb7 no hardware scale-up"},shot:{src:"/work/eventus-platform.jpg",alt:"Eventus platform public website",caption:"Eventus platform (public site)"},story:{context:"Eventus Security’s in-house SOC analytics product",problem:"Customers depended on external tools like Trend Micro. The goal was one dashboard where clients see their advisories, security alerts, threat data and KPI metrics in real time.",built:["Full stack: NestJS backend APIs, a Next.js + TypeScript frontend and Apache ECharts visualisations.","Real-time KPI widgets for active alerts, threat counts and resolved incidents.","Search over security data with date ranges and Lucene queries against OpenSearch."],challenge:{title:"Hundreds of millions of records without timeouts",body:"Some searches touched hundreds of millions of records, so the backend timed out and the dashboard froze. I rewrote the pagination logic, pushed heavy computation into MongoDB aggregation pipelines so the database did the work, and added Redis caching for frequently requested data. As a team we then moved the analytics workloads from MongoDB to ClickHouse, and I optimised the ClickHouse queries for real-time security events, cutting query times well below MongoDB’s."},result:"The dashboard became faster, more responsive and scalable, and customers could monitor security data in real time without leaning on external tools.",before:{label:"Analytics store",from:"MongoDB",to:"ClickHouse"}}},{name:"Health Check Automation",trace:"health",kind:"Internal platform",blurb:"27 dynamic charts and 30+ page DOCX/PDF reports generated from raw Excel exports.",stack:["MERN","SheetJS","Chart.js"],stat:"20 h → 1 h",spotlight:{where:"At work \xb7 Eventus Security",outcome:"16–20 hours → under 1 hour per report \xb7 27 charts \xb7 adopted by the whole team"},shot:{src:"/work/health-check.jpg",alt:"Illustration of the Health Check reporting dashboard"},story:{context:"My first project at Eventus, as an Associate Software Developer, built completely on my own without AI tools",problem:"The customer success team spent 16 to 20 hours preparing each client health-check report by hand: copying data, building charts one by one, formatting documents.",built:["A full-stack Node.js and React app: upload an Excel file, the data is processed, 27 charts are generated and a fully formatted report is exported as both PDF and Word.","A dashboard to view reports and analytics, with create, update and delete for reports.","Role-based access for Developer, Root User, Health Check User and Viewer, each with different permissions.","Security headers, rate limiting, input sanitisation and two-factor authentication with time-bound OTPs.","A global error-handling middleware that catches unexpected errors gracefully."],challenge:{title:"Blank charts in the exported PDF",body:"All 27 charts rendered asynchronously, so the PDF could be generated before they finished and come out with blank charts. I used Promises to wait for every chart to finish rendering before starting the PDF export."},result:"Once deployed, the same report was ready in under an hour, and the customer success team adopted the tool completely.",before:{label:"Report preparation",from:"16–20 h",to:"< 1 h"},extras:[{title:"Decisions",items:["Started on MySQL, then moved to MongoDB once the report schemas became semi-structured, for flexibility."]}],tradeoff:"The app was I/O-heavy with low traffic, so reports were generated in the request. With heavier reports or many concurrent users, I would move generation to a job queue."}},{name:"Reqway",trace:"reqway",kind:"Postman-style API client",blurb:"Compose, send and organise HTTP requests: a server-side proxy engine, collections, environments with variable substitution, auth helpers, paginated history and code snippets.",stack:["React","Node.js","Express","MongoDB","JWT"],stat:"Postman-style",shot:{src:"/work/screens/reqway-request-response.jpg",alt:"Reqway: a request with its formatted JSON response"},gallery:[{src:"/work/screens/reqway-request-response.jpg",alt:"Request builder and JSON response",caption:"Request & response"},{src:"/work/screens/reqway-snippets.jpg",alt:"Generated code snippets for a request",caption:"Code snippets"},{src:"/work/screens/reqway-history.jpg",alt:"Request history list",caption:"History"},{src:"/work/screens/reqway-environments.jpg",alt:"Environments manager",caption:"Environments"},{src:"/work/screens/reqway-login.jpg",alt:"Sign-in screen",caption:"Sign in"}],github:"https://github.com/roshnithakor07/coderepo-react-node-postman",story:{context:"A Postman-style API client I built end to end",problem:"Testing an API from the browser runs into CORS, and a useful client needs much more than “send”: saved collections, environments, auth, history and code you can paste into your app.",built:["A server-side proxy engine that executes every request, so any API can be called from the browser, with a 30-second timeout, decompression and status-agnostic responses.","A request builder with {{variable}} highlighting, two-way sync between the URL and the Params tab, Bearer / Basic / API-key auth, and bulk edit for key-value tables.","Collections with unique request names, save-in-place, clone and rename; named environments resolved at send time; paginated history.","Code snippets for curl, fetch, axios and Python, generated with the environment variables already filled in.","Express 5 on Bun, one folder per feature (routes → controller → service → repository), Zod validation and one error handler that never leaks stack traces."],challenge:{title:"Huge responses without freezing the page",body:"Rendering a large JSON response as a fully expanded tree locks up the browser. The Pretty view is a virtualized tree: only the rows on screen are rendered, with expand and collapse all, and in-response search that counts matches and jumps between them."},result:"A complete API client: compose, send, inspect, save and share requests, covered by end-to-end API tests that run against a disposable MongoDB database.",extras:[{title:"Decisions",items:["Partial updates never reset fields the client didn’t send.","No component, state or icon libraries: one CSS design system of tokens, and keyboard-accessible menus."]}]}},{name:"Support Desk",trace:"supportdesk",kind:"Customer support ticketing",blurb:"Ticketing with role-based access and agent teams, SLA tracking with automatic breach alerts, merge and bulk actions, and a full activity log; 40 product rules, each proven by tests.",stack:["React","Node.js","Express","MongoDB","JWT"],stat:"132 rule tests",spotlight:{where:"Side project",outcome:"40 product rules \xb7 132 tests \xb7 SLA breach alerts \xb7 video walkthrough"},shot:{src:"/work/screens/support-desk-analytics.jpg",alt:"Support Desk analytics: ticket volume, SLA compliance and resolution times"},gallery:[{src:"/work/screens/support-desk-dashboard.jpg",alt:"Dashboard with ticket stats and recent tickets",caption:"Dashboard"},{src:"/work/screens/support-desk-tickets.jpg",alt:"Ticket list with SLA status and filters",caption:"Tickets & SLA"},{src:"/work/screens/support-desk-ticket-detail.jpg",alt:"Ticket detail with replies and status",caption:"Ticket detail"},{src:"/work/screens/support-desk-analytics.jpg",alt:"Analytics charts",caption:"Analytics"},{src:"/work/screens/support-desk-activity.jpg",alt:"Activity log of ticket changes",caption:"Activity log"},{src:"/work/screens/support-desk-agents.jpg",alt:"Agents and their categories",caption:"Agents & teams"},{src:"/work/screens/support-desk-login.jpg",alt:"Sign-in screen with demo roles",caption:"Sign in"}],github:"https://github.com/roshnithakor07/coderepo-react-node-support-desk",video:"https://drive.google.com/file/d/1TzRcNZNis5zJPfZPnjUlP-kVZ_yzQ-8h/view",story:{context:"A customer-support ticketing platform for customers, agents and admins",problem:"Support tools go wrong in the details: tickets that skip steps, SLA clocks that quietly reset, and agents who can grab work outside their team. Every rule had to hold, not just the happy path.",built:["40 product rules enforced in the service layer, each with its own error code (for example 409 INVALID_TRANSITION) and its own test.","A ticket lifecycle that moves one step at a time, with a 14-day reopen window; resolving needs a public reply from the team.","Agent teams: access is decided twice, by role and by category, and new tickets go to the least-loaded agent who covers them.","Merge, bulk actions, canned responses, a full activity log, in-app notifications and an analytics dashboard.","Rate-limited sign-in, and signed-out tokens stored as hashes that expire on their own, so a restart never undoes a sign-out."],challenge:{title:"An SLA clock you can trust",body:"The deadline moves only on a reopen or a priority change on a live ticket, and a breach is permanent. A sweep runs every minute, flags overdue tickets as the system (not a person) and tells every admin; if a sweep is still running when the next is due, the next one is skipped, never doubled."},result:"40 rules, each proven by tests (132 in total), plus a video walkthrough of the customer, agent and admin flows."}},{name:"QuizCraft",trace:"labs",kind:"AI quiz generator",blurb:"Up to 200 questions from text or images in 24 languages, with PDF/Word export and response dashboards.",stack:["Next.js 14","Groq","NextAuth"],stat:"24 languages",ai:!0,shot:{src:"/work/quizcraft.jpg",alt:"QuizCraft: paste text, pick language, difficulty and number of questions"},live:"https://quizcraft-mauve.vercel.app/",github:"https://github.com/roshnithakor07/quizcraft",story:{context:"An AI quiz generator, live on Vercel",problem:"Writing a good quiz from your notes takes hours: questions, options, an answer key, a printable copy, and a way to collect answers.",built:["Quiz generation with Groq from pasted text or uploaded images, in 24 languages including Hindi and Gujarati, at easy, medium or hard difficulty.","Share links anyone can take without signing up, with an instant score and review.","A results dashboard with every response, score and timestamp.","Export to PDF or Word, with or without the answer key.","Email and password sign-in with NextAuth, plus a guest mode for trying it out."],challenge:{title:"200 questions don’t fit in one model call",body:"Long quizzes overflow a single LLM response, so generation is split into batches: each call asks for a slice of the questions and the results are stitched into one quiz."},result:"Live on Vercel: paste a chapter, get a quiz with an answer key, share it, and watch the results come in."}},{name:"QuickLink",trace:"quicklink",kind:"URL shortener & analytics API",blurb:"Redis cache-aside on the redirect path cut latency from ~120 ms to ~4 ms, with sliding-window rate limiting, JWT roles (free / pro / admin) and click analytics by day, device and referrer.",stack:["TypeScript","Express","MongoDB","Redis","Next.js"],stat:"120 → 4 ms",shot:{src:"/work/quicklink.svg",alt:"Illustration of QuickLink: a short link, redirect latency and click analytics"},github:"https://github.com/roshnithakor07/quicklink",story:{context:"A URL shortener and click-analytics API, TypeScript end to end",problem:"A short link is only useful if the redirect is instant, abuse is held back, and the owner can see who clicked.",built:["An Express + TypeScript API with a thin controller → service layering, and a Next.js 14 dashboard.","Sliding-window rate limiting on Redis sorted sets, per user: 10 requests a minute on free, 100 on pro.","JWT roles (free / pro / admin) as Express middleware; analytics are a pro feature, so free users get a 403.","Click analytics by day, device and referrer, computed with MongoDB aggregation pipelines.","Cursor-based pagination, and link expiry handled by a MongoDB TTL index instead of a cron job."],challenge:{title:"Redirects in milliseconds",body:"Every redirect looked up its short code in MongoDB, about 120 ms. I put a cache-aside layer on the redirect path: check Redis first, fall back to MongoDB on a miss and cache the result. Hits now resolve in about 4 ms, and a defensive check covers the gap before the TTL index purges an expired link."},result:"Redirects went from ~120 ms to ~4 ms on a cache hit, with rate limits and analytics that scale with the plan.",before:{label:"Redirect latency",from:"~120 ms",to:"~4 ms"}}},{name:"Calendly",trace:"calendly",kind:"Scheduling & availability API",blurb:"Timezone-aware availability with race-safe booking in PostgreSQL transactions, and Temporal workflows that send confirmations, sync Google Calendar and regenerate slots.",stack:["TypeScript","Express","PostgreSQL","Prisma","Temporal"],stat:"race-safe booking",shot:{src:"/work/calendly.svg",alt:"Illustration of the scheduling API: a week of free and busy slots with a confirmed booking"},github:"https://github.com/roshnithakor07/calendly",story:{context:"A scheduling and availability API in the spirit of Calendly",problem:"Scheduling looks simple until two people book the same slot at the same moment, hosts and invitees sit in different timezones, and emails or calendar sync fail halfway.",built:["Onboarding with availability windows and a personal booking-page slug.","A timezone-aware availability engine built with Luxon.","Google Calendar OAuth2: booked meetings are created on the host’s calendar.","Temporal workflows after each booking: confirmation email, Google Calendar event and slot regeneration, retried durably if a step fails.","Express + TypeScript with Prisma on PostgreSQL, and Zod validation on every request."],challenge:{title:"Two invitees, one slot",body:"Booking runs inside a Prisma transaction, in two strategies. Optimistic: mark the slot booked only if it is still free, and fail unless exactly one row changed. Pessimistic: lock the slot row first (SELECT … FOR UPDATE), then book it. Either way only one of two simultaneous requests can win."},result:"A double booking can’t happen, and the slow side effects (email, calendar) run as durable workflows instead of blocking the request.",tradeoff:"Optimistic booking is cheaper when collisions are rare; the row lock is simpler to reason about when a popular slot gets hammered."}},{name:"ComplexityIQ",trace:"labs",kind:"Big-O analyser",blurb:"Best, average and worst-case analysis for 9 languages with auto-refactor and a zero-dependency SVG chart.",stack:["Next.js 14","Groq","SVG"],stat:"9 languages",ai:!0,shot:{src:"/work/complexityiq.jpg",alt:"ComplexityIQ: paste code and get a Big-O analysis"},github:"https://github.com/roshnithakor07/complexity-iq",story:{context:"An AI-powered Big-O analyser for 9 languages",problem:"Knowing your code’s time and space complexity, and why, usually means reasoning through every loop by hand.",built:["Time and space analysis with best, average and worst cases, loop and recursion detection, and the exact bottleneck.","Auto-refactor for weak code: optimised code in the same language, with a before/after comparison of what changed.","Compare mode: two versions analysed in parallel, with a verdict.","A zero-dependency SVG growth chart that highlights your complexity class, and a history with a score trend."],challenge:{title:"Analysing the right language",body:"Pasted code often doesn’t match the language picked in the dropdown, and the analysis suffers. I built a detector that scores the code against 40+ signals per language, warns on a mismatch and switches with one click, in both the analyser and compare mode."},result:"Paste code in any of 9 languages and get a complexity report, a chart and, when it helps, a faster version of the same code."}}],i=[{degree:"B.E. in Information Technology",school:"Saffrony Institute of Technology",university:"Gujarat Technological University",when:"Jul 2018 - May 2022",place:"Mehsana, Gujarat",scores:[{k:"CGPA",v:"9.0"},{k:"CPI",v:"8.85"}],logo:"/logos/gtu-new.png",logoText:"GTU",schoolUrl:"https://saffrony.ac.in/",universityUrl:"https://www.gtu.ac.in/"}],l={hrms:{label:"Smile HRMS",href:"#work"},eventus:{label:"Eventus",href:"#work"},interns:{label:"Internships",href:"#work"},devlens:{label:"DevLens",href:"#project-devlens"},esdl:{label:"ESDL Dashboard",href:"#project-esdl-dashboard"},health:{label:"Health Check",href:"#project-health-check-automation"},quiz:{label:"QuizCraft",href:"#project-quizcraft"},ciq:{label:"ComplexityIQ",href:"#project-complexityiq"},orch:{label:"HackerRank Orchestrate",href:"#awards"},site:{label:"This portfolio",href:"#top"},quick:{label:"QuickLink",href:"#project-quicklink"},cal:{label:"Calendly API",href:"#project-calendly"},reqway:{label:"Reqway",href:"#project-reqway"},desk:{label:"Support Desk",href:"#project-support-desk"}},c=[{sym:"No",name:"Node.js",group:"Backend",uses:[l.hrms,l.eventus,l.health,l.interns,l.quick,l.cal,l.reqway,l.desk]},{sym:"Ne",name:"NestJS",group:"Backend",uses:[l.hrms,l.devlens,l.esdl]},{sym:"Ex",name:"Express",group:"Backend",uses:[l.health,l.interns,l.quick,l.cal,l.reqway,l.desk]},{sym:"Ra",name:"REST APIs",group:"Backend",uses:[l.hrms,l.eventus,l.devlens,l.esdl,l.health,l.quick,l.cal,l.reqway,l.desk]},{sym:"Jw",name:"JWT / RBAC",group:"Backend",uses:[l.hrms,l.devlens,l.health,l.quick,l.cal,l.reqway,l.desk]},{sym:"Mt",name:"Multi-tenancy",group:"Backend",uses:[l.hrms]},{sym:"Ts",name:"TypeScript",group:"Languages",uses:[l.hrms,l.devlens,l.esdl,l.quick,l.cal]},{sym:"Js",name:"JavaScript",group:"Languages",uses:[l.quiz,l.ciq,l.health,l.interns,l.reqway,l.desk]},{sym:"Py",name:"Python",group:"Languages",uses:[]},{sym:"Jv",name:"Java",group:"Languages",uses:[]},{sym:"Re",name:"React",group:"Frontend",uses:[l.esdl,l.devlens,l.health,l.quiz,l.ciq,l.reqway,l.desk]},{sym:"Nx",name:"Next.js",group:"Frontend",uses:[l.devlens,l.esdl,l.quiz,l.ciq]},{sym:"Tw",name:"Tailwind CSS",group:"Frontend",uses:[l.ciq]},{sym:"Ec",name:"ECharts",group:"Frontend",uses:[l.esdl]},{sym:"Pg",name:"PostgreSQL",group:"Data",uses:[l.hrms,l.cal]},{sym:"Mg",name:"MongoDB",group:"Data",uses:[l.devlens,l.health,l.quiz,l.esdl,l.interns,l.reqway,l.desk]},{sym:"Ch",name:"ClickHouse",group:"Data",uses:[l.esdl]},{sym:"Rd",name:"Redis",group:"Data",uses:[l.esdl,l.quick,l.cal]},{sym:"Pr",name:"Prisma",group:"Data",uses:[l.esdl,l.quick,l.cal]},{sym:"To",name:"TypeORM",group:"Data",uses:[l.hrms]},{sym:"My",name:"MySQL",group:"Data",uses:[l.interns,l.quick]},{sym:"Dk",name:"Docker",group:"Platform",uses:[l.hrms,l.eventus]},{sym:"S3",name:"AWS S3",group:"Platform",uses:[l.hrms]},{sym:"Jt",name:"Jest",group:"Platform",uses:[l.hrms,l.esdl]},{sym:"Gt",name:"Git",group:"Platform",uses:[l.hrms,l.eventus,l.devlens]},{sym:"Cl",name:"Claude API",group:"AI",uses:[l.devlens,l.orch]},{sym:"Cc",name:"Claude Code",group:"AI",uses:[l.site]},{sym:"Gq",name:"Groq",group:"AI",uses:[l.quiz,l.ciq]},{sym:"Gm",name:"Gemini",group:"AI",uses:[]},{sym:"Ag",name:"Google Antigravity",group:"AI",uses:[]},{sym:"Cx",name:"Codex",group:"AI",uses:[]},{sym:"Cu",name:"Cursor",group:"AI",uses:[]}],d=[{group:"Backend",items:["Node.js","NestJS","Express","REST APIs","JWT / RBAC","Multi-tenancy"]},{group:"Languages",items:["TypeScript","JavaScript","Python","Java (SE)"]},{group:"Frontend",items:["React","Next.js","Tailwind CSS","ECharts"]},{group:"Data",items:["PostgreSQL","MongoDB","ClickHouse","Redis","Prisma","TypeORM","MySQL"]},{group:"Platform",items:["Docker","AWS S3","Jest","Git"]},{group:"AI",items:["Claude API","Claude Code","Groq","Gemini","Google Antigravity","Codex","Cursor"]}],h=[{title:"Top 3.4%",event:"Orchestrate Oct '26",rank:"#139 of 4,094",sub:"#139 of 4,094 \xb7 HackerRank Orchestrate \xb7 Oct 2026",note:"AI agent pipeline that detects ghost data left behind after deletion.",shot:{src:"/work/orchestrate-oct-2026.jpg",alt:"HackerRank Orchestrate certificate, October 2026: rank 139 of 4,094"},link:"https://www.hackerrank.com/contests/hackerrank-orchestrate-october26/challenges/ghost-data-still-exists/leaderboard?username=roshnithakor07"},{title:"Top 18.5%",event:"Orchestrate Aug '26",rank:"#367 of 1,983",sub:"#367 of 1,983 \xb7 HackerRank Orchestrate \xb7 Aug 2026",note:"Multimodal notification router built on the Claude API.",shot:{src:"/work/orchestrate-aug-2026.jpg",alt:"HackerRank Orchestrate certificate, August 2026: rank 367 of 1,983"},link:"https://www.hackerrank.com/contests/hackerrank-orchestrate-august26/challenges/message-notification-router/leaderboard?username=roshnithakor07"},{title:"Top 26%",event:"Orchestrate Jun '26",rank:"#460 of 1,773",sub:"#460 of 1,773 \xb7 HackerRank Orchestrate \xb7 Jun 2026",note:"Multimodal insurance-claim verification agent built on vision-language models.",shot:{src:"/work/orchestrate-jun-2026.jpg",alt:"HackerRank Orchestrate certificate, June 2026: rank 460 of 1,773"},link:"https://github.com/roshnithakor07/multimodal-damage-claim-verification",linkLabel:"GitHub Repo"}]}}]);